#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QCoreApplication>
#include <BRepClass3d_SolidClassifier.hxx>
#include <QTemporaryDir>
#include <QJsonDocument>
#include <numbers>
#include <cmath>
#include <iostream>
void check(bool ok,const QString& message){if(!ok)throw std::runtime_error(message.toStdString());}
QJsonObject sources(CadDocument& d,bool clip=true){
    const auto owner=d.activeOwnerId();auto profile=SketchGeometry::addCircle(SketchGeometry::newFeature(owner,"XZ","Circle section"),{{"centerUMm",0},{"centerVMm",0},{"diameterMm",2}});auto path=SketchGeometry::newFeature(owner,"XY","Analytic path foundation");
    auto line=[&](double x1,double y1,double x2,double y2){path=SketchGeometry::addLine(path,{{"u1Mm",x1},{"v1Mm",y1},{"u2Mm",x2},{"v2Mm",y2}});};
    auto arc=[&](double x,double y,double radius,double start,double sweep){path=SketchGeometry::addArc(path,{{"centerUMm",x},{"centerVMm",y},{"radiusMm",radius},{"startAngleDeg",start},{"sweepAngleDeg",sweep}});};
    line(0,0,0,clip?33:10);if(clip){arc(7,33,7,180,-90);arc(7,33,7,90,-90);line(14,33,14,-14.5);arc(8.5,-14.5,5.5,0,-90);arc(8.5,-14.5,5.5,-90,-90);line(3,-14.5,3,20);arc(7,20,4,180,-90);arc(7,20,4,90,-90);line(11,20,11,0);}
    auto authored=SketchGeometry::replaceFeature(d.authored(),profile);authored=SketchGeometry::replaceFeature(authored,path);check(d.commit(authored,"Sources").isEmpty(),"source commit");QJsonArray ids;for(const auto& e:path["parameters"].toObject()["entities"].toArray())ids.append(e.toObject()["id"]);return {{"ownerId",owner},{"profileSketchId",profile["id"]},{"profileId",d.sketches().front().profiles.front().profileId},{"pathSketchId",path["id"]},{"pathEntityIds",ids},{"pathStartPointId",path["parameters"].toObject()["entities"].toArray().first().toObject()["startPointId"]}};
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
    CadDocument d;auto args=sources(d);const auto before=d.authored();auto candidate=CadDocument::sweepCandidate(before,args);auto eval=CadDocument::evaluateCandidate(candidate);check(eval.ok,eval.error+QString::fromUtf8(QJsonDocument(eval.diagnostics).toJson()));check(d.authored()==before && d.bodies().empty(),"preview detached");check(d.commit(candidate,"Sweep").isEmpty(),"commit");const auto body=d.bodies().front();const double length=135+16.5*std::numbers::pi,volume=length*std::numbers::pi;check(std::abs(body.summary["pathLengthMm"].toDouble()-length)<1e-7,"analytic path length");check(std::abs(body.summary["volumeMm3"].toDouble()-volume)<1e-5,"analytic volume");check(body.supportFaces.size()==2 && body.supportFaces[0].faceId!=body.supportFaces[1].faceId,"exact caps");const auto min=body.summary["boundsMm"].toObject()["min"].toArray(),max=body.summary["boundsMm"].toObject()["max"].toArray();for(int i=0;i<3;++i){check(std::abs(min[i].toDouble()-QJsonArray{-1,-21,-1}[i].toDouble())<1e-6,"min bounds");check(std::abs(max[i].toDouble()-QJsonArray{15,41,1}[i].toDouble())<1e-6,"max bounds");}
    for(const auto& cap:body.supportFaces){const auto o=cap.frame["origin"].toArray(),n=cap.frame["normal"].toArray();const gp_Pnt origin(o[0].toDouble(),o[1].toDouble(),o[2].toDouble());const gp_Vec normal(n[0].toDouble(),n[1].toDouble(),n[2].toDouble());BRepClass3d_SolidClassifier outside(body.shape,origin.Translated(normal*.0001),1e-7),inside(body.shape,origin.Translated(normal*-.0001),1e-7);check(outside.State()==TopAbs_OUT && inside.State()==TopAbs_IN,"cap frames actually outward");}
    const auto accepted=d.authored();d.history().undo();check(d.authored()==before,"undo exact");d.history().redo();check(d.authored()==accepted,"redo exact");args["featureId"]=body.featureId;check(d.commit(CadDocument::sweepCandidate(d.authored(),args),"Edit retained").isEmpty() && d.bodies().front().bodyId==body.bodyId,"feature edit identity");
    auto refuse=[&](QJsonObject bad,const QString& code){const auto state=d.authored();const auto revision=d.revision();const QJsonValue undo=d.state()["undo"];check(!d.commit(CadDocument::sweepCandidate(state,bad),"Refused").isEmpty(),"bad sweep should fail");check(d.lastEvaluationError()["code"]==code,"unexpected diagnostic "+QString::fromUtf8(QJsonDocument(d.lastEvaluationError()).toJson()));check(d.authored()==state && d.revision()==revision && d.state()["undo"]==undo,"atomic refusal");};
    auto missingProfile=args;missingProfile["profileId"]=CadDocument::newId();refuse(missingProfile,"profile_unavailable");
    auto bad=args;auto ids=args["pathEntityIds"].toArray();ids[0]=CadDocument::newId();bad["pathEntityIds"]=ids;refuse(bad,"path_entity_unavailable");bad=args;ids=args["pathEntityIds"].toArray();auto first=ids.takeAt(0);ids.append(first);bad["pathEntityIds"]=ids;refuse(bad,"disconnected_path");
    auto misaligned=d.authored();auto misFeatures=misaligned["features"].toArray();auto misProfile=misFeatures[0].toObject();auto misParams=misProfile["parameters"].toObject();auto misPoints=misParams["points"].toArray();auto misCenter=misPoints[0].toObject();misCenter["uMm"]=.01;misPoints[0]=misCenter;misParams["points"]=misPoints;misProfile["parameters"]=misParams;misFeatures[0]=misProfile;misaligned["features"]=misFeatures;check(!d.commit(misaligned,"Misaligned source").isEmpty() && d.lastEvaluationError()["code"]=="profile_start_misaligned" && d.authored()==accepted,"circle center alignment atomic");
    // Radius2 overlaps nonadjacent legs separated by3mm, despite regular returns.
    auto collision=d.authored();auto fs=collision["features"].toArray();auto profile=fs[0].toObject();auto p=profile["parameters"].toObject();auto es=p["entities"].toArray();auto circle=es[0].toObject();circle["radiusMm"]=2;es[0]=circle;p["entities"]=es;profile["parameters"]=p;fs[0]=profile;collision["features"]=fs;check(!d.commit(collision,"Colliding section").isEmpty(),"self overlapping sweep refused");check(d.lastEvaluationError()["code"]=="sweep_self_intersection","geometric overlap diagnostic");check(d.authored()==accepted,"overlap atomic");
    // Supported profile radius and terminal path edits retain all references.
    auto edit=accepted;fs=edit["features"].toArray();profile=fs[0].toObject();p=profile["parameters"].toObject();es=p["entities"].toArray();circle=es[0].toObject();circle["radiusMm"]=.8;es[0]=circle;p["entities"]=es;profile["parameters"]=p;fs[0]=profile;auto path=fs[1].toObject();p=path["parameters"].toObject();auto points=p["points"].toArray();const QJsonValue end=p["entities"].toArray().last().toObject()["endPointId"];for(int i=0;i<points.size();++i){auto q=points[i].toObject();if(q["id"]==end){q["vMm"]=-2;points[i]=q;}}p["points"]=points;path["parameters"]=p;fs[1]=path;edit["features"]=fs;check(d.commit(edit,"Source edits").isEmpty(),"supported source edits");check(d.bodies().front().bodyId==body.bodyId && d.bodies().front().supportFaces[1].faceId==body.supportFaces[1].faceId,"retained body/caps");check(std::abs(d.bodies().front().summary["volumeMm3"].toDouble()-.64*std::numbers::pi*(length+2))<1e-5,"edited volume");
    // Shared solver connectivity, exact zero-gap endpoints and direction are
    // retained; neither path order nor approximate endpoint coordinates choose it.
    CadDocument junction;auto junctionArgs=sources(junction,false);auto source=junction.authored()["features"].toArray()[1].toObject();auto kink=SketchGeometry::addLine(source,{{"u1Mm",0},{"v1Mm",10},{"u2Mm",5},{"v2Mm",10}});auto kinkIds=junctionArgs["pathEntityIds"].toArray();kinkIds.append(kink["parameters"].toObject()["entities"].toArray().last().toObject()["id"]);check(junction.commit(SketchGeometry::replaceFeature(junction.authored(),kink),"Kink source").isEmpty(),"kink source");junctionArgs["pathEntityIds"]=kinkIds;check(!junction.commit(CadDocument::sweepCandidate(junction.authored(),junctionArgs),"Kink refused").isEmpty() && junction.lastEvaluationError()["code"]=="non_g1_path","nonG1 diagnostic");
    auto gap=SketchGeometry::addLine(source,{{"u1Mm",0},{"v1Mm",10.00000001},{"u2Mm",0},{"v2Mm",20}});check(junction.commit(SketchGeometry::replaceFeature(junction.authored(),gap),"Gap source").isEmpty(),"gap source");auto gapIds=QJsonArray{};for(const auto& e:gap["parameters"].toObject()["entities"].toArray())gapIds.append(e.toObject()["id"]);junctionArgs["pathEntityIds"]=gapIds;check(!junction.commit(CadDocument::sweepCandidate(junction.authored(),junctionArgs),"Gap refused").isEmpty() && junction.lastEvaluationError()["code"]=="disconnected_path","10nm gap not healed");
    auto corrected=SketchGeometry::addConstraint(gap,{{"type","coincident"},{"pointIds",QJsonArray{gap["parameters"].toObject()["entities"].toArray().first().toObject()["endPointId"],gap["parameters"].toObject()["entities"].toArray().last().toObject()["startPointId"]}}});check(corrected.ok,"coincident correction solves");check(junction.commit(SketchGeometry::replaceFeature(junction.authored(),corrected.feature),"Coincident source").isEmpty(),"corrected source");check(junction.commit(CadDocument::sweepCandidate(junction.authored(),junctionArgs),"Corrected Sweep").isEmpty(),"declared connectivity accepted");
    auto branch=SketchGeometry::addLine(corrected.feature,{{"u1Mm",0},{"v1Mm",10},{"u2Mm",-5},{"v2Mm",10}});check(junction.commit(SketchGeometry::replaceFeature(junction.authored(),branch),"Branch source").isEmpty(),"branch source retained existing subset");auto branchIds=gapIds;branchIds.append(branch["parameters"].toObject()["entities"].toArray().last().toObject()["id"]);auto branchArgs=junctionArgs;branchArgs["pathEntityIds"]=branchIds;check(!junction.commit(CadDocument::sweepCandidate(junction.authored(),branchArgs),"Branch refused").isEmpty() && junction.lastEvaluationError()["code"]=="branched_path","branch ambiguity refused");
    CadDocument component;auto componentDoc=CadDocument::componentCandidate(component.authored(),"Sweep owner");const auto componentId=componentDoc["components"].toArray().last().toObject()["id"].toString();check(component.commit(componentDoc,"Component").isEmpty() && component.activateOwner(componentId).isEmpty(),"component owner");auto owned=sources(component,false);check(component.commit(CadDocument::sweepCandidate(component.authored(),owned),"Owned Sweep").isEmpty() && component.bodies().front().ownerId==componentId,"component ownership");
    QTemporaryDir tmp;check(d.save(tmp.filePath("sweep.alloy")).isEmpty(),"save");CadDocument reopened;check(reopened.open(tmp.filePath("sweep.alloy")).isEmpty() && reopened.authored()==d.authored(),"reopen exact");
    CadDocument straight;auto straightArgs=sources(straight,false);check(straight.commit(CadDocument::sweepCandidate(straight.authored(),straightArgs),"Straight").isEmpty(),"straight antiparallel normal");check(std::abs(straight.bodies().front().summary["volumeMm3"].toDouble()-10*std::numbers::pi)<1e-6,"straight volume");
    auto positive=straight.authored();auto positiveFeatures=positive["features"].toArray();auto reverseSource=positiveFeatures[1].toObject();auto reverseP=reverseSource["parameters"].toObject();auto reversePoints=reverseP["points"].toArray();for(int i=0;i<reversePoints.size();++i){auto q=reversePoints[i].toObject();if(q["vMm"].toDouble()==10){q["vMm"]=-10;reversePoints[i]=q;}}reverseP["points"]=reversePoints;reverseSource["parameters"]=reverseP;positiveFeatures[1]=reverseSource;positive["features"]=positiveFeatures;check(straight.commit(positive,"Parallel normal sign").isEmpty(),"parallel normal sign accepted");
    std::cout<<"PASS analytic G1 Sweep/line, exact references/caps, edits, overlap refusal/history/storage\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
